172:     // P4M bank 448..463. Word 0 tags the capability; every other word is the snapshot taken
173:     // at the (open, close] closing boundary and never changes afterwards.
174:     always_comb begin
175:         p4m_data = '0;
176:         case (index_q)
177:             9'd448: p4m_data = 64'h49444d4150344d01;
178:             9'd449: p4m_data = 64'(p4m_cycles_q);
179:             9'd450: p4m_data = 64'(p4m_a_issue_q);
180:             9'd451: p4m_data = 64'(p4m_a_done_q);
181:             9'd452: p4m_data = {63'b0, p4m_start_q};
182:             9'd453: p4m_data = {63'b0, p4m_end_q};
183:             9'd454: p4m_data = {63'b0, p4m_carry_done_q};
184:             9'd455: p4m_data = {63'b0, p4m_open_issue_q};
185:             9'd456: p4m_data = p4m_open_id_q;
186:             9'd457: p4m_data = p4m_close_id_q;
187:             9'd458: p4m_data = p4m_first_done_id_q;
188:             9'd459: p4m_data = p4m_last_done_id_q;
189:             9'd460: p4m_data = 64'(p4m_error_q);
190:             9'd461: p4m_data = 64'(p4m_window_issue_q);
191:             9'd462: p4m_data = 64'(p4m_window_done_q);
192:             9'd463: p4m_data = {61'b0, p4m_carry_q, p4m_closed_q, has_a_q};

241:         // Track continuously, including warmup and drain, never reset on ARM.
242:         for (int i = 0; i < NumPorts; i++) begin
243:             reads_n[i] = reads_q[i];
244:             writes_n[i] = writes_q[i];
245:             case ({ar_valid_i[i] && ar_ready_i[i], rlast_fire_i[i]})
246:                 2'b10: begin
247:                     reads_n[i] = reads_q[i] + 1'b1;
248:                     if (&reads_q[i]) track_bad_n[i] = 1'b1;
249:                 end
250:                 2'b01: begin
251:                     reads_n[i] = reads_q[i] - 1'b1;
252:                     if (reads_q[i] == 0) track_bad_n[i] = 1'b1;
253:                 end
254:                 default: ; // Simultaneous acceptance/return has zero net change.
255:             endcase
256:             case ({aw_valid_i[i] && aw_ready_i[i], b_fire_i[i]})
257:                 2'b10: begin
258:                     writes_n[i] = writes_q[i] + 1'b1;
259:                     if (&writes_q[i]) track_bad_n[i] = 1'b1;
260:                 end
261:                 2'b01: begin
262:                     writes_n[i] = writes_q[i] - 1'b1;
263:                     if (writes_q[i] == 0) track_bad_n[i] = 1'b1;
264:                 end
265:                 default: ;
266:             endcase
267:             if (bad_id_i[i]) track_bad_n[i] = 1'b1;
268:         end

336:         if (phase_q == ARMED && issue_i[victim_q]) begin
337:             phase_n = HARDWARE;
338:             expected_n = issue_id_i[victim_q];
339:             count_n[7] = 1;
340:             segment_n = 0;
341:             count_n[30] = CounterWidth'((CounterWidth'(reads_n[victim_q]) << 16) | CounterWidth'(writes_n[victim_q]));
342:             count_n[31] = has_a_q ? CounterWidth'((CounterWidth'(reads_n[aggressor_q]) << 16) | CounterWidth'(writes_n[aggressor_q])) : '0;
343:             if (issue_id_i[victim_q] == 0) error_n[1] = 1'b1;
344:             if (p4m_q) begin
345:                 // Opening edge. This cycle's lane events are excluded from the sums, the selected
346:                 // lane stock is sampled after them, and a selected job that was not issued here is
347:                 // the immutable strict pre-opening cohort. The opening job itself counts as the
348:                 // first V issue of the window, matching legacy count7.
349:                 p4m_open_n = 1'b1;
350:                 p4m_start_n = has_a_q && lane_task_n[aggressor_q];
351:                 p4m_end_n = 1'b0;
352:                 p4m_open_id_n = (has_a_q && lane_task_n[aggressor_q]) ? lane_id_n[aggressor_q] : 64'd0;
353:                 p4m_open_issue_n = a_issue_evt;
354:                 p4m_carry_n = has_a_q && lane_task_n[aggressor_q] && !a_issue_evt;
355:                 p4m_carry_done_n = 1'b0;
356:                 p4m_window_issue_n = 1'b1;
357:             end

373:         if (active) begin
374:             bump(0, 1'b1);
375:             segment_n = segment_q + 1'b1;
376:             if (&segment_q) error_n[2] = 1'b1;
377:             bump(10 + int'({a_pending, v_pending}), 1'b1);
378:             for (int role = 0; role < 2; role++) begin
379:                 if (role == 0 || has_a_q) begin
380:                     bump(14 + role*6, ar_valid_i[role == 0 ? victim_q : aggressor_q] && ar_ready_i[role == 0 ? victim_q : aggressor_q]);
381:                     bump(15 + role*6, aw_valid_i[role == 0 ? victim_q : aggressor_q] && aw_ready_i[role == 0 ? victim_q : aggressor_q]);
382:                     bump(16 + role*6, rlast_fire_i[role == 0 ? victim_q : aggressor_q]);
383:                     bump(17 + role*6, b_fire_i[role == 0 ? victim_q : aggressor_q]);
384:                     bump(18 + role*6, ar_valid_i[role == 0 ? victim_q : aggressor_q] && !ar_ready_i[role == 0 ? victim_q : aggressor_q]);
385:                     bump(19 + role*6, aw_valid_i[role == 0 ? victim_q : aggressor_q] && !aw_ready_i[role == 0 ? victim_q : aggressor_q]);
386:                 end
387:             end
388:             bump(26, shared_ar_valid_i && shared_ar_ready_i);
389:             bump(27, shared_aw_valid_i && shared_aw_ready_i);
390:             bump(28, shared_ar_valid_i && !shared_ar_ready_i);
391:             bump(29, shared_aw_valid_i && !shared_aw_ready_i);

